import{_ as p,a0 as d,w as o,s as r,I as a,x as n,a1 as i,A as l,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 ncdu 檢查 Linux 中的可用磁盤空間 | LCTT x X-CMD","titleTemplate":false,"description":"用 ncdu 檢查 Linux 中的可用磁盤空間 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 ncdu 檢查 Linux 中的可用磁盤空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 ncdu 檢查 Linux 中的可用磁盤空間 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210819 Check free disk space in Linux with ncdu","title":"用 ncdu 檢查 Linux 中的可用磁盤空間","tag":"202108","desc":""},"relativePath":"202108/20210819 Check free disk space in Linux with ncdu.md","filePath":"[post].md"}'),u={name:"202108/20210819 Check free disk space in Linux with ncdu.md"};function c(h,s,k,g,f,b){const e=d("Link");return o(),r("div",null,[s[33]||(s[33]=a("h1",{id:"用-ncdu-檢查-linux-中的可用磁盤空間",tabindex:"-1"},[n("用 ncdu 檢查 Linux 中的可用磁盤空間 "),a("a",{class:"header-anchor",href:"#用-ncdu-檢查-linux-中的可用磁盤空間","aria-label":"Permalink to “用 ncdu 檢查 Linux 中的可用磁盤空間”"},"​")],-1)),s[34]||(s[34]=a("blockquote",null,[a("p",null,"用 ncdu Linux 命令獲得關於磁盤使用的交互式報告。")],-1)),s[35]||(s[35]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/29/095819e87oz4ox6p40t6q0.jpg",alt:""})],-1)),a("p",null,[s[2]||(s[2]=n("計算機用户多年來往往積累了大量的數據，無論是重要的個人項目、數碼照片、視頻、音樂還是代碼庫。雖然現在的硬盤往往相當大，但有時你必須退一步，評估一下你在硬盤上實際存儲了什麼。經典的 Linux 命令 ",-1)),i(e,{href:"https://opensource.com/article/21/7/check-disk-space-linux-df"},{default:l(()=>[...s[0]||(s[0]=[n("df",-1)])]),_:1}),s[3]||(s[3]=n(" 和 ",-1)),i(e,{href:"https://opensource.com/article/21/7/check-disk-space-linux-du"},{default:l(()=>[...s[1]||(s[1]=[n("du",-1)])]),_:1}),s[4]||(s[4]=n(" 是快速瞭解硬盤上的內容的方法，它們提供了一個可靠的報告，易於解析和處理。這對腳本和處理來説是很好的，但人的大腦對數百行的原始數據並不總是反應良好。認識到這一點，",-1)),s[5]||(s[5]=a("code",null,"ncdu",-1)),s[6]||(s[6]=n(" 命令旨在提供一份關於你在硬盤上使用的空間的交互式報告。",-1))]),s[36]||(s[36]=t('<h3 id="在-linux-上安裝-ncdu" tabindex="-1">在 Linux 上安裝 ncdu <a class="header-anchor" href="#在-linux-上安裝-ncdu" aria-label="Permalink to “在 Linux 上安裝 ncdu”">​</a></h3><p>在 Linux 上，你可以從你的軟件倉庫安裝 <code>ncdu</code>。例如，在 Fedora 或 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncdu</span></span></code></pre></div>',3)),a("p",null,[s[8]||(s[8]=n("在 BSD 上，你可以使用 ",-1)),i(e,{href:"https://opensource.com/article/19/11/pkgsrc-netbsd-linux"},{default:l(()=>[...s[7]||(s[7]=[n("pkgsrc",-1)])]),_:1}),s[9]||(s[9]=n("。",-1))]),a("p",null,[s[12]||(s[12]=n("在 macOS 上，你可以從 ",-1)),i(e,{href:"https://opensource.com/article/20/11/macports"},{default:l(()=>[...s[10]||(s[10]=[n("MacPorts",-1)])]),_:1}),s[13]||(s[13]=n(" 或 ",-1)),i(e,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:l(()=>[...s[11]||(s[11]=[n("HomeBrew",-1)])]),_:1}),s[14]||(s[14]=n(" 安裝。",-1))]),a("p",null,[s[16]||(s[16]=n("另外，你也可以 ",-1)),i(e,{href:"https://dev.yorhel.nl/ncdu"},{default:l(()=>[...s[15]||(s[15]=[n("從源碼編譯 ncdu",-1)])]),_:1}),s[17]||(s[17]=n("。",-1))]),s[37]||(s[37]=t(`<h3 id="使用-ncdu" tabindex="-1">使用 ncdu <a class="header-anchor" href="#使用-ncdu" aria-label="Permalink to “使用 ncdu”">​</a></h3><p><code>ncdu</code> 界面使用 ncurses 庫，它將你的終端窗口變成一個基本的圖形應用，所以你可以使用方向鍵來瀏覽菜單。</p><p><img src="https://opensource.com/sites/default/files/ncdu.jpg" alt="ncdu interface" title="ncdu interface"></p><p>這是 <code>ncdu</code> 的主要吸引力之一，也是它與最初的 <code>du</code> 命令不同的地方。</p><p>要獲得一個目錄的完整列表，啓動 <code>ncdu</code>。它默認為當前目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu</span></span>
<span class="line"><span>ncdu 1.16 ~ Use the arrow keys to navigate, press ? for help                                                                  </span></span>
<span class="line"><span>--- /home/tux -----------------------------------------------</span></span>
<span class="line"><span>   22.1 GiB [##################] /.var</span></span>
<span class="line"><span>   19.0 GiB [###############   ] /Iso</span></span>
<span class="line"><span>   10.0 GiB [########          ] /.local</span></span>
<span class="line"><span>    7.9 GiB [######            ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>    3.6 GiB [##                ] /.mail</span></span>
<span class="line"><span>    2.9 GiB [##                ] /Code</span></span>
<span class="line"><span>    2.8 GiB [##                ] /Documents</span></span>
<span class="line"><span>    2.3 GiB [#                 ] /Videos</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這個列表首先顯示了最大的目錄（在這個例子中，那是 <code>~/.var</code> 目錄，塞滿了很多的 flatpak 包）。</p><p>使用鍵盤上的方向鍵，你可以瀏覽列表，深入到一個目錄，這樣你就可以更好地瞭解什麼東西佔用了最大的空間。</p><h3 id="獲取一個特定目錄的大小" tabindex="-1">獲取一個特定目錄的大小 <a class="header-anchor" href="#獲取一個特定目錄的大小" aria-label="Permalink to “獲取一個特定目錄的大小”">​</a></h3><p>你可以在啓動 <code>ncdu</code> 時提供任意一個文件夾的路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu ~/chromiumos</span></span></code></pre></div><h3 id="排除目錄" tabindex="-1">排除目錄 <a class="header-anchor" href="#排除目錄" aria-label="Permalink to “排除目錄”">​</a></h3><p>默認情況下，<code>ncdu</code> 包括一切可以包括的東西，包括符號鏈接和偽文件系統，如 procfs 和 sysfs。你可以用 <code>--exclude-kernfs</code> 來排除這些。</p><p>你可以使用 <code>--exclude</code> 選項排除任意文件和目錄，並在後面加上一個匹配模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --exclude &quot;.var&quot;</span></span>
<span class="line"><span>   19.0 GiB [##################] /Iso</span></span>
<span class="line"><span>   10.0 GiB [#########         ] /.local</span></span>
<span class="line"><span>    7.9 GiB [#######           ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>另外，你可以在文件中列出要排除的文件和目錄，並使用 <code>--exclude-from</code> 選項來引用該文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --exclude-from myexcludes.txt /home/tux</span></span>
<span class="line"><span>   10.0 GiB [#########         ] /.local</span></span>
<span class="line"><span>    7.9 GiB [#######           ] /.cache</span></span>
<span class="line"><span>    3.8 GiB [###               ] /Downloads</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="顏色方案" tabindex="-1">顏色方案 <a class="header-anchor" href="#顏色方案" aria-label="Permalink to “顏色方案”">​</a></h3><p>你可以用 <code>--color dark</code> 選項給 <code>ncdu</code> 添加一些顏色。</p><p><img src="https://opensource.com/sites/default/files/ncdu-dark.jpg" alt="ncdu color scheme" title="ncdu color scheme"></p><h3 id="包括符號鏈接" tabindex="-1">包括符號鏈接 <a class="header-anchor" href="#包括符號鏈接" aria-label="Permalink to “包括符號鏈接”">​</a></h3><p><code>ncdu</code> 輸出按字面意思處理符號鏈接，這意味着一個指向 9GB 文件的符號鏈接只佔用 40 個字節。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu ~/Iso</span></span>
<span class="line"><span>    9.3 GiB [##################]  CentOS-Stream-8-x86_64-20210427-dvd1.iso                                                    </span></span>
<span class="line"><span>@   0.0   B [                  ]  fake.iso</span></span></code></pre></div><p>你可以用 <code>--follow-symlinks</code> 選項強制 ncdu 跟蹤符號鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncdu --follow-symlinks ~/Iso</span></span>
<span class="line"><span>    9.3 GiB [##################]  fake.iso                                                                                    </span></span>
<span class="line"><span>    9.3 GiB [##################]  CentOS-Stream-8-x86_64-20210427-dvd1.iso</span></span></code></pre></div><h3 id="磁盤使用率" tabindex="-1">磁盤使用率 <a class="header-anchor" href="#磁盤使用率" aria-label="Permalink to “磁盤使用率”">​</a></h3><p>磁盤空間用完並不有趣，所以監控你的磁盤使用情況很重要。<code>ncdu</code> 命令使它變得簡單和互動。下次當你對你的電腦上存儲的東西感到好奇時，或者只是想以一種新的方式探索你的文件系統時，不妨試試 <code>ncdu</code>。</p><hr>`,28)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),i(e,{href:"https://opensource.com/article/21/8/ncdu-check-free-disk-space-linux"},{default:l(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/21/8/ncdu-check-free-disk-space-linux",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[20]||(s[20]=[n("Seth Kenlon",-1)])]),_:1}),s[25]||(s[25]=n(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[30]||(s[30]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...s[29]||(s[29]=[n("Linux中國",-1)])]),_:1}),s[32]||(s[32]=n(" 榮譽推出",-1))])])}const y=p(u,[["render",c]]);export{C as __pageData,y as default};
